package application.domain.services.fulfillment;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import application.domain.exceptions.*; import java.util.*;
public class UpdateShipmentStatusService implements UpdateShipmentStatusUseCase { private final ShipmentRepositoryPort shipments; private final OrderRepositoryPort orders; private final OperationAuditPort audit; public UpdateShipmentStatusService(ShipmentRepositoryPort s,OrderRepositoryPort o,OperationAuditPort a){shipments=s;orders=o;audit=a;}
 public Shipment updateShipmentStatus(User actor,String sid,DomainTypes.ShipmentStatus status){ServiceSupport.role(actor,"ADMIN","EMPLOYEE","SELLER");Shipment s=ServiceSupport.required(shipments.findById(sid),"Shipment",sid);if(!valid(s.getStatus(),status))throw new DomainRuleException("Invalid shipment status transition");s.changeStatus(status);shipments.update(s);Order o=s.getOrder();if(status==DomainTypes.ShipmentStatus.IN_TRANSIT)o.changeStatus(DomainTypes.OrderStatus.SHIPPED);if(status==DomainTypes.ShipmentStatus.DELIVERED)o.changeStatus(DomainTypes.OrderStatus.DELIVERED);if(status==DomainTypes.ShipmentStatus.RETURNED)o.changeStatus(DomainTypes.OrderStatus.RETURN_REQUESTED);orders.update(o);audit.record(actor,"UPDATE_SHIPMENT_STATUS",sid,Map.of("status",status.name()));return s;}
 private boolean valid(DomainTypes.ShipmentStatus a,DomainTypes.ShipmentStatus b){return (a==DomainTypes.ShipmentStatus.CREATED&&b==DomainTypes.ShipmentStatus.IN_TRANSIT)||(a==DomainTypes.ShipmentStatus.IN_TRANSIT&&(b==DomainTypes.ShipmentStatus.DELIVERED||b==DomainTypes.ShipmentStatus.RETURNED))||a==b;}
}
